solution = [0, 2, 4, 1, 3, 8, 10, 12, 14, 20, 22, 24, 19, 21, 23, 25, 9, 6, 15, 11, 7, 5, 17, 13, 18, 16]

print("Full verification of 26-Queens solution:")
print(f"{'Row':>4} {'Col':>4}")
for i, c in enumerate(solution):
    print(f"{i:>4} {c:>4}")

# Check all constraints
n = 26
errors = []
for i in range(n):
    for j in range(i+1, n):
        ci, cj = solution[i], solution[j]
        if ci == cj:
            errors.append(f"Rows {i}&{j} share column {ci}")
        if abs(ci - cj) == abs(i - j):
            errors.append(f"Rows {i}&{j} on same diagonal")

if errors:
    print("ERRORS:", errors)
else:
    print("\n✓ All 26 queens placed — no two share a row, column, or diagonal!")
    print(f"✓ Solution: {solution}")
